// Services to monitor - CUSTOMIZE THESE
const services = [
  { name: 'n8n',        url: 'http://localhost:5678/healthz',    expected_status: 200, expected_body: 'ok', timeout_ms: 5000,  alert_after_failures: 2 },
  { name: 'API Server', url: 'https://api.example.com/health',    expected_status: 200,                     timeout_ms: 10000, alert_after_failures: 3 },
  { name: 'Website',    url: 'https://example.com',               expected_status: 200,                     timeout_ms: 15000, alert_after_failures: 2 }
];

return services.map(s => ({ json: s }));

// Evaluate health check results with persistent failure counters.
// NOTE: /home/node/.n8n/health-state is a mounted volume in docker-compose.yml.
// Without that volume, counters reset on every container restart.
const items = $input.all();
const fs = require('fs');
const STATE_DIR  = '/home/node/.n8n/health-state';
const STATE_FILE = `${STATE_DIR}/health-state.json`;

try { fs.mkdirSync(STATE_DIR, { recursive: true }); } catch(e) {}

let state = {};
try { state = JSON.parse(fs.readFileSync(STATE_FILE, 'utf8')); } catch(e) {}

const alerts = [];
const recoveries = [];

for (const item of items) {
  const name = item.json.name;
  const status = item.json.statusCode;
  const expected = item.json.expected_status || 200;
  const threshold = item.json.alert_after_failures || 2;
  const healthy = status === expected;

  if (!state[name]) state[name] = { failures: 0, alerted: false, down_since: null };

  if (!healthy) {
    state[name].failures++;
    if (!state[name].down_since) state[name].down_since = new Date().toISOString();
    if (state[name].failures >= threshold && !state[name].alerted) {
      state[name].alerted = true;
      alerts.push({ name, status, failures: state[name].failures, down_since: state[name].down_since });
    }
  } else {
    if (state[name].alerted) {
      const downtime = state[name].down_since ? Math.round((Date.now() - new Date(state[name].down_since)) / 60000) : 0;
      recoveries.push({ name, downtime_minutes: downtime });
    }
    state[name] = { failures: 0, alerted: false, down_since: null };
  }
}

fs.writeFileSync(STATE_FILE, JSON.stringify(state));

const results = [];
for (const a of alerts)     results.push({ json: { type: 'alert',    message: `\uD83D\uDD34 DOWN: ${a.name} (status ${a.status}, ${a.failures} failures since ${a.down_since})` } });
for (const r of recoveries) results.push({ json: { type: 'recovery', message: `\u2705 RECOVERED: ${r.name} (was down ${r.downtime_minutes}min)` } });

return results.length > 0 ? results : [{ json: { type: 'ok', message: 'All services healthy' } }];

// No-op branch for healthy state. Kept so the IF false branch has a sink
// and executions render cleanly in the UI.
return [{ json: { ok: true, at: new Date().toISOString() } }];
